-- Additive group tools. Preview is explicit per account; it is not a paid grant.
CREATE TABLE community_group_policy(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),ends_at INTEGER NOT NULL DEFAULT 0);
INSERT INTO community_group_policy(id,enabled,ends_at) VALUES(1,1,0);
CREATE TABLE community_group_previews(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE community_group_roles(room_id TEXT NOT NULL REFERENCES community_rooms(id) ON DELETE CASCADE,profile_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,created_at INTEGER NOT NULL,PRIMARY KEY(room_id,profile_id));
CREATE TRIGGER community_group_role_limit BEFORE INSERT ON community_group_roles WHEN (SELECT count(*) FROM community_group_roles WHERE room_id=NEW.room_id)>=2 BEGIN SELECT RAISE(ABORT,'GROUP_ROLE_LIMIT'); END;
CREATE TABLE community_group_settings(room_id TEXT PRIMARY KEY REFERENCES community_rooms(id) ON DELETE CASCADE,scene TEXT NOT NULL DEFAULT 'mist-lake',music TEXT NOT NULL DEFAULT 'meditation-01',quiet_chat INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE community_group_tasks(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES community_rooms(id) ON DELETE CASCADE,title TEXT NOT NULL,subject TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,archived INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TRIGGER community_group_task_limit BEFORE INSERT ON community_group_tasks WHEN (SELECT count(*) FROM community_group_tasks WHERE room_id=NEW.room_id AND archived=0)>=50 BEGIN SELECT RAISE(ABORT,'GROUP_TASK_LIMIT'); END;
CREATE TABLE community_group_task_claims(task_id TEXT NOT NULL REFERENCES community_group_tasks(id) ON DELETE CASCADE,profile_id TEXT NOT NULL REFERENCES community_profiles(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN('working','done')),updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(task_id,profile_id));
CREATE TABLE community_group_series(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES community_rooms(id) ON DELETE CASCADE,subject TEXT NOT NULL,kind TEXT NOT NULL,local_date TEXT NOT NULL,local_time TEXT NOT NULL,zone TEXT NOT NULL,fold TEXT NOT NULL DEFAULT 'earlier',weekdays TEXT NOT NULL,focus_minutes INTEGER NOT NULL,break_minutes INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
ALTER TABLE community_activities ADD COLUMN series_id TEXT REFERENCES community_group_series(id) ON DELETE SET NULL;
ALTER TABLE community_activities ADD COLUMN series_version INTEGER NOT NULL DEFAULT 0;
CREATE TABLE community_group_challenges(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES community_rooms(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN('minutes','activities')),goal INTEGER NOT NULL,start_day TEXT NOT NULL,end_day TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX community_group_one_challenge ON community_group_challenges(room_id) WHERE archived=0;
CREATE TABLE community_group_reports(room_id TEXT NOT NULL REFERENCES community_rooms(id) ON DELETE CASCADE,week TEXT NOT NULL,body TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(room_id,week));
DROP TRIGGER community_room_owner_limit;
DROP TRIGGER community_room_owner_update_limit;
CREATE TRIGGER community_room_owner_limit BEFORE INSERT ON community_rooms WHEN NEW.closed_at=0 AND (SELECT count(*) FROM community_rooms WHERE owner_id=NEW.owner_id AND closed_at=0 AND id<>NEW.id)>=CASE WHEN EXISTS(SELECT 1 FROM community_entitlements e JOIN community_profiles p ON p.account_id=e.account_id WHERE p.id=NEW.owner_id AND e.expires_at>NEW.created_at) OR EXISTS(SELECT 1 FROM community_group_previews gp JOIN community_profiles p ON p.account_id=gp.account_id JOIN community_group_policy pol ON pol.id=1 WHERE p.id=NEW.owner_id AND gp.enabled=1 AND pol.enabled=1 AND (pol.ends_at=0 OR pol.ends_at>NEW.created_at)) THEN 10 ELSE 1 END BEGIN SELECT RAISE(ABORT,'ROOM_LIMIT'); END;
CREATE TRIGGER community_room_owner_update_limit BEFORE UPDATE OF owner_id,closed_at ON community_rooms WHEN NEW.closed_at=0 AND (OLD.closed_at<>0 OR OLD.owner_id<>NEW.owner_id) AND (SELECT count(*) FROM community_rooms WHERE owner_id=NEW.owner_id AND closed_at=0 AND id<>NEW.id)>=CASE WHEN EXISTS(SELECT 1 FROM community_entitlements e JOIN community_profiles p ON p.account_id=e.account_id WHERE p.id=NEW.owner_id AND e.expires_at>unixepoch('now')*1000) OR EXISTS(SELECT 1 FROM community_group_previews gp JOIN community_profiles p ON p.account_id=gp.account_id JOIN community_group_policy pol ON pol.id=1 WHERE p.id=NEW.owner_id AND gp.enabled=1 AND pol.enabled=1 AND (pol.ends_at=0 OR pol.ends_at>unixepoch('now')*1000)) THEN 10 ELSE 1 END BEGIN SELECT RAISE(ABORT,'ROOM_LIMIT'); END;
DROP TRIGGER community_join_limit;
CREATE TRIGGER community_join_limit BEFORE INSERT ON community_members WHEN NEW.banned=0 AND NEW.left_at=0 AND (SELECT owner_id FROM community_rooms WHERE id=NEW.room_id)<>NEW.profile_id AND (SELECT count(*) FROM community_members m JOIN community_rooms r ON r.id=m.room_id WHERE m.profile_id=NEW.profile_id AND r.owner_id<>NEW.profile_id AND m.banned=0 AND m.left_at=0 AND r.closed_at=0)>=10 BEGIN SELECT RAISE(ABORT,'MEMBERSHIP_LIMIT'); END;
DROP TRIGGER community_rejoin_limit;
CREATE TRIGGER community_rejoin_limit BEFORE UPDATE OF left_at,banned ON community_members WHEN (OLD.left_at>0 OR OLD.banned=1) AND NEW.banned=0 AND NEW.left_at=0 AND (SELECT owner_id FROM community_rooms WHERE id=NEW.room_id)<>NEW.profile_id AND (SELECT count(*) FROM community_members m JOIN community_rooms r ON r.id=m.room_id WHERE m.profile_id=NEW.profile_id AND r.owner_id<>NEW.profile_id AND m.banned=0 AND m.left_at=0 AND r.closed_at=0)>=10 BEGIN SELECT RAISE(ABORT,'MEMBERSHIP_LIMIT'); END;

CREATE TRIGGER community_group_series_limit BEFORE INSERT ON community_group_series WHEN NEW.enabled=1 AND (SELECT count(*) FROM community_group_series WHERE room_id=NEW.room_id AND enabled=1)>=5 BEGIN SELECT RAISE(ABORT,'GROUP_SERIES_LIMIT'); END;
CREATE TRIGGER community_group_series_resume_limit BEFORE UPDATE OF enabled ON community_group_series WHEN OLD.enabled=0 AND NEW.enabled=1 AND (SELECT count(*) FROM community_group_series WHERE room_id=NEW.room_id AND enabled=1 AND id<>NEW.id)>=5 BEGIN SELECT RAISE(ABORT,'GROUP_SERIES_LIMIT'); END;

CREATE INDEX community_group_tasks_room ON community_group_tasks(room_id,archived,created_at DESC);
CREATE INDEX community_group_series_room ON community_group_series(room_id,enabled);
CREATE INDEX community_activities_series ON community_activities(series_id,series_version);
CREATE INDEX community_room_daily_report ON community_room_daily(room_id,day);
